const b = $json.body;
const freq = b.payment_frequency || 'annual';
const n = { single: 1, monthly: 12, quarterly: 4, semiannual: 2, annual: 1 }[freq] || 1;
const amountEach = Math.round((b.premium_total / n) * 100) / 100;
const start = new Date(b.start_date);
const monthsStep = { single: 0, monthly: 1, quarterly: 3, semiannual: 6, annual: 12 }[freq] || 12;
const installments = [];
for (let i = 0; i < n; i++) {
  const d = new Date(start);
  d.setMonth(d.getMonth() + monthsStep * i);
  installments.push({ installment_no: i + 1, amount: amountEach, due_date: d.toISOString().slice(0,10) });
}
return [{ json: { ...b, installments } }];

const policy = $json; // id, contact_id, currency (de 'Insertar póliza')
const installments = $('POST policy → calcular cuotas').item.json.installments;
return installments.map(i => ({ json: {
  policy_id: policy.id,
  contact_id: policy.contact_id,
  installment_no: i.installment_no,
  amount: i.amount,
  currency: policy.currency,
  due_date: i.due_date
}}));

