select count(*)::int as solapes from public.appointments
where status in ('scheduled','confirmed')
  and tstzrange(starts_at, ends_at) && tstzrange($1::timestamptz, $2::timestamptz);

insert into public.appointments (contact_id, title, purpose, starts_at, ends_at, status)
select c.id, $2, $3, $4::timestamptz, $5::timestamptz, 'scheduled'
from public.contacts c where c.phone = regexp_replace($1, '\D', '', 'g')
returning id, starts_at, ends_at;

update public.claims set status = $2, amount_paid = coalesce($3, amount_paid), updated_at = now()
where id = $1
returning id, status;

