// El panel manda { event, payload: { n8n_webhook?, whatsapp?, google_calendar? } }.
// Nunca debe llegar un token/secreto real aca (viven en el Credentials Store de n8n),
// pero se filtra por si acaso antes de guardarlo en integration_settings.
const SECRET_KEYS = ['token', 'apikey', 'api_key', 'secret', 'password', 'authorization'];
function stripSecrets(obj) {
  const clean = {};
  for (const [k, v] of Object.entries(obj || {})) {
    if (SECRET_KEYS.some(s => k.toLowerCase().includes(s))) continue;
    clean[k] = v;
  }
  return clean;
}

const payload = $json.body?.payload || {};
const rows = [];

if (payload.n8n_webhook) {
  rows.push({
    integration_type: 'n8n_webhook',
    provider: null,
    is_active: !!payload.n8n_webhook.is_active,
    metadata: stripSecrets(payload.n8n_webhook)
  });
}
if (payload.whatsapp) {
  rows.push({
    integration_type: 'whatsapp',
    provider: payload.whatsapp.provider || null,
    is_active: !!payload.whatsapp.is_active,
    metadata: stripSecrets(payload.whatsapp)
  });
}
if (payload.google_calendar) {
  rows.push({
    integration_type: 'google_calendar',
    provider: null,
    is_active: !!payload.google_calendar.is_active,
    metadata: stripSecrets(payload.google_calendar)
  });
}

return rows.map(r => ({ json: r }));

